<?php
class Proyecto_lote extends CI_Controller {
    var $session_data; const ROL_LOTES=225; const ROL_RESERVAS=226;
    public function __construct(){ parent::__construct(); $this->load->model(array('Proyecto_lote_model','Proyecto_model','Producto_model','Inventario_model')); if($this->session->userdata('logged_in'))$this->session_data=$this->session->userdata('logged_in');else{ $this->output->set_status_header(401); exit; } $this->output->set_content_type('application/json'); }
    private function acceso($id){ if((int)$this->session_data['tipousuario_id']===1)return true; $r=$this->session_data['rol']; return isset($r[$id-1])&&(int)$r[$id-1]['rolusuario_asignado']===1; }
    private function deny(){ echo json_encode(array('success'=>false,'message'=>'No tiene permiso para esta operación.')); exit; }
    public function listar($pid){ if(!$this->acceso(self::ROL_LOTES))$this->deny(); echo json_encode($this->Proyecto_lote_model->get_by_proyecto((int)$pid,$this->input->get('estado'))); }
    public function resumen($pid){ if(!$this->acceso(self::ROL_LOTES))$this->deny(); echo json_encode($this->Proyecto_lote_model->resumen((int)$pid)); }
    public function obtener($id){ if(!$this->acceso(self::ROL_LOTES))$this->deny(); echo json_encode(array('lote'=>$this->Proyecto_lote_model->get_by_id((int)$id),'historial'=>$this->Proyecto_lote_model->historial((int)$id),'reservas'=>$this->Proyecto_lote_model->reservas((int)$id),'ventas'=>$this->Proyecto_lote_model->ventas((int)$id))); }
    public function guardar(){
        if(!$this->acceso(self::ROL_LOTES))$this->deny(); $id=(int)$this->input->post('proyecto_lote_id'); $pid=(int)$this->input->post('proyecto_id'); $cod=trim($this->input->post('lote_codigo')); $p=$this->Proyecto_model->get_by_id($pid);
        if(!$p||$cod===''){ echo json_encode(array('success'=>false,'message'=>'Proyecto o código de lote inválido.')); return; }
        if($this->Proyecto_lote_model->existe_codigo($pid,$cod,$id)){ echo json_encode(array('success'=>false,'message'=>'Ya existe ese código de lote en el proyecto.')); return; }
        $precio=(float)$this->input->post('precio'); $es_nuevo=($id===0); $this->db->trans_begin();
        if($id){ $l=$this->Proyecto_lote_model->get_by_id($id); $producto_id=(int)$l['producto_id']; $this->Producto_model->update_producto($producto_id,array('producto_codigo'=>$cod,'producto_nombre'=>'LOTE '.$cod.' - '.$p['proyecto_nombre'],'producto_precio'=>$precio)); }
        else { $params=array('estado_id'=>1,'categoria_id'=>(int)$p['categoria_id'],'presentacion_id'=>1,'moneda_id'=>(int)$p['moneda_id'],'producto_codigo'=>$cod,'producto_nombre'=>'LOTE '.$cod.' - '.$p['proyecto_nombre'],'producto_unidad'=>'UNIDAD','producto_costo'=>0,'producto_precio'=>$precio,'producto_catalogo'=>0); $producto_id=$this->Producto_model->add_producto($params); $this->Inventario_model->ingresar_producto_inventario($producto_id); }
        $meta=array('proyecto_id'=>$pid,'producto_id'=>$producto_id,'lote_codigo'=>$cod,'uv'=>trim($this->input->post('uv')),'manzano'=>trim($this->input->post('manzano')),'numero'=>trim($this->input->post('numero')),'superficie'=>(float)$this->input->post('superficie'),'geojson'=>$this->input->post('geojson'),'descripcion'=>trim($this->input->post('descripcion')),'usuario_id'=>(int)$this->session_data['usuario_id']);
        if($id)$this->Proyecto_lote_model->update($id,$meta); else { $meta['estado_lote']='DISPONIBLE'; $meta['fecha_registro']=date('Y-m-d H:i:s'); $id=$this->Proyecto_lote_model->add($meta); }
        $this->Proyecto_lote_model->historial_add($id,$es_nuevo?'CREACION':'ACTUALIZACION','Producto Ximpleman #'.$producto_id,(int)$this->session_data['usuario_id']);
        if($this->db->trans_status()===false){$this->db->trans_rollback();echo json_encode(array('success'=>false,'message'=>'No se pudo guardar el lote.'));return;} $this->db->trans_commit(); echo json_encode(array('success'=>true,'message'=>'Lote guardado como producto Ximpleman.','lote_id'=>$id,'producto_id'=>$producto_id));
    }
    public function guardar_poligono(){ if(!$this->acceso(self::ROL_LOTES))$this->deny(); $id=(int)$this->input->post('lote_id'); $this->Proyecto_lote_model->update($id,array('geojson'=>$this->input->post('geojson'),'usuario_id'=>(int)$this->session_data['usuario_id'])); $this->Proyecto_lote_model->historial_add($id,'POLIGONO','Polígono actualizado',(int)$this->session_data['usuario_id']); echo json_encode(array('success'=>true)); }
    public function reservar(){
        if(!$this->acceso(self::ROL_RESERVAS))$this->deny(); $id=(int)$this->input->post('lote_id'); $cliente=(int)$this->input->post('cliente_id'); if(!$id||!$cliente){echo json_encode(array('success'=>false,'message'=>'Seleccione lote y cliente.'));return;}
        $this->db->trans_begin(); $this->Proyecto_lote_model->cancelar_reservas_activas($id); $this->Proyecto_lote_model->reserva_add(array('proyecto_lote_id'=>$id,'cliente_id'=>$cliente,'monto_reserva'=>(float)$this->input->post('monto'),'observacion'=>trim($this->input->post('observacion')),'estado'=>'ACTIVA','usuario_id'=>(int)$this->session_data['usuario_id'],'fecha_reserva'=>date('Y-m-d H:i:s'))); $this->Proyecto_lote_model->update($id,array('estado_lote'=>'RESERVADO','cliente_id'=>$cliente)); $this->Proyecto_lote_model->historial_add($id,'RESERVA','Lote reservado',(int)$this->session_data['usuario_id']); if($this->db->trans_status()===false){$this->db->trans_rollback();echo json_encode(array('success'=>false,'message'=>'No se pudo reservar.'));return;} $this->db->trans_commit(); echo json_encode(array('success'=>true,'message'=>'Reserva registrada.'));
    }
    public function liberar(){ if(!$this->acceso(self::ROL_RESERVAS))$this->deny(); $id=(int)$this->input->post('lote_id'); $this->Proyecto_lote_model->cancelar_reservas_activas($id); $this->Proyecto_lote_model->update($id,array('estado_lote'=>'DISPONIBLE','cliente_id'=>null)); $this->Proyecto_lote_model->historial_add($id,'LIBERACION','Lote liberado',(int)$this->session_data['usuario_id']); echo json_encode(array('success'=>true,'message'=>'Lote liberado.')); }
}
